+const { READ, COMMENT, WRITE, ADMIN } = require('./rights');
+
+const OWNER = READ | COMMENT | WRITE | ADMIN;
+
+function transferOwnership(doc, fromUser, toUser) {
+  doc.shares[fromUser] &= ~ADMIN;
+  doc.shares[toUser] = OWNER;
+  doc.owner = toUser;
+}
+
+module.exports = { transferOwnership, OWNER };
