 console.log(JSON.stringify({name,mask,actualCanEdit:canEdit({mask,locked:false}),expectedCanEdit:hasRight(mask,WRITE)}));
}
let mismatches=[];
for(let mask=0;mask<16;mask++) for(const locked of [false,true]) {
 if(Boolean(canEdit({mask,locked})) !== (hasRight(mask,WRITE)&&!locked)) mismatches.push({mask,locked});
 if(canComment({mask,locked}) !== (hasRight(mask,COMMENT)&&!locked)) throw new Error('comment mismatch');
 for(const right of [READ,COMMENT,WRITE,ADMIN]) if(toggleRight(toggleRight(mask,right),right)!==mask) throw new Error('toggle mismatch');
}
console.log('Edit permission mismatches:',JSON.stringify(mismatches));
for(let mask=0;mask<16;mask++) {
 const doc={owner:'a',shares:{a:mask,b:READ}};
 transferOwnership(doc,'a','b');
 if(doc.shares.a!==(mask&~ADMIN)||doc.shares.b!==OWNER||doc.owner!=='b') throw new Error('transfer mismatch');
